mapper.sql:
occurred_at >= #{q.from} AND occurred_at < #{q.to}
AND id = #{q.id}
AND operator_tenant_id = #{q.operatorTenantId}
AND operator_employee_no = #{q.operatorEmployeeNo}
AND request_id = #{q.requestId}

SELECT id, 'ACCESS' AS source, request_id,
       CASE WHEN action = 'UPDATE_API_GOVERNANCE' THEN target_id ELSE NULL END AS api_id,
       application_id, target_tenant_id AS tenant_id, target_id, action, outcome,
       'ADMIN' AS actor_kind, operator_tenant_id, operator_employee_no,
       NULL AS release_id, NULL AS draft_revision, occurred_at
FROM access_audit
WHERE 
AND target_id = #{q.targetId}
AND 'ACCESS' IN
    #{source}

AND action = 'UPDATE_API_GOVERNANCE' AND target_id = #{q.apiId}
AND application_id = #{q.applicationId}
AND target_tenant_id = #{q.tenantId}
AND outcome IN
    #{outcome}

UNION ALL
SELECT id, 'TOKEN', request_id, NULL, application_id, tenant_id, token_id, action, outcome,
       actor_kind, operator_tenant_id, operator_employee_no, NULL, NULL, occurred_at
FROM token_audit
WHERE 
AND token_id = #{q.targetId}
AND 'TOKEN' IN
    #{source}

AND 1 = 0
AND application_id = #{q.applicationId}
AND tenant_id = #{q.tenantId}
AND outcome IN
    #{outcome}

UNION ALL
SELECT id, 'CATALOG', request_id, api_id, NULL, NULL, api_id, action, 'SUCCESS',
       'ADMIN', operator_tenant_id, operator_employee_no, NULL, draft_revision, occurred_at
FROM catalog_audit
WHERE environment_id=#{environmentId} AND 
AND api_id = #{q.targetId}
AND 'CATALOG' IN
    #{source}

AND api_id = #{q.apiId}
AND 1 = 0
AND 'SUCCESS' IN
    #{outcome}

UNION ALL
SELECT id, 'PUBLICATION', request_id, api_id, NULL, NULL, api_id, action, outcome,
       'ADMIN', operator_tenant_id, operator_employee_no, release_id, NULL, occurred_at
FROM publication_audit
WHERE environment_id=#{environmentId} AND 
AND api_id = #{q.targetId}
AND 'PUBLICATION' IN
    #{source}

AND api_id = #{q.apiId}
AND 1 = 0
AND outcome IN
    #{outcome}
